import{_ as i}from"./chunks/Audio.COine8Wh.js";import{c as o,o as r,j as t,G as s,ae as a,a as n}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"ADDRESSING THREATS TO THE UNITED STATES BY THE GOVERNMENT OF BRAZIL","description":"","frontmatter":{"legisId":"2025-07-30-addressing-threats-to-the-united-states-by-the-government-of-brazil","title":"ADDRESSING THREATS TO THE UNITED STATES BY THE GOVERNMENT OF BRAZIL","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/07/addressing-threats-to-the-us/","publishDate":"2025-07-30T14:30:05-04:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"ADDRESSING THREATS TO THE UNITED STATES BY THE GOVERNMENT OF BRAZIL\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-07-30-addressing-threats-to-the-united-states-by-the-government-of-brazil\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"ADDRESSING THREATS TO THE UNITED STATES BY THE GOVERNMENT OF BRAZIL\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-07-30-addressing-threats-to-the-united-states-by-the-government-of-brazil\\",\\"datePublished\\":\\"2025-07-30T14:30:05-04:00\\",\\"dateModified\\":1777602859000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-07-30-addressing-threats-to-the-united-states-by-the-government-of-brazil\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-07-30-addressing-threats-to-the-united-states-by-the-government-of-brazil.md","filePath":"executive-orders/2025-07-30-addressing-threats-to-the-united-states-by-the-government-of-brazil.md","lastUpdated":1777602859000}'),l={name:"executive-orders/2025-07-30-addressing-threats-to-the-united-states-by-the-government-of-brazil.md"},c=Object.assign(l,{setup(d){return(h,e)=>(r(),o("div",null,[e[0]||(e[0]=t("h1",{id:"addressing-threats-to-the-united-states-by-the-government-of-brazil",tabindex:"-1"},[n("ADDRESSING THREATS TO THE UNITED STATES BY THE GOVERNMENT OF BRAZIL "),t("a",{class:"header-anchor",href:"#addressing-threats-to-the-united-states-by-the-government-of-brazil","aria-label":'Permalink to "ADDRESSING THREATS TO THE UNITED STATES BY THE GOVERNMENT OF BRAZIL"'},"​")],-1)),s(i),e[1]||(e[1]=a('<p>Published on Wednesday, July 30, 2025</p><ul><li><p><strong>Authority</strong>: The executive order is issued under various U.S. laws, notably the IEEPA and NEA.</p></li><li><p><strong>National Security Threat</strong>: Actions by the Brazilian Government threaten U.S. national security, foreign policy, and economy through:</p><ul><li>Interference with the U.S. economy.</li><li>Violations of free expression rights of U.S. persons.</li><li>Human rights abuses.</li><li>Political persecution of former Brazilian President Jair Bolsonaro.</li></ul></li><li><p><strong>Judicial Abuse</strong>: Brazilian officials, particularly Justice Alexandre de Moraes, have engaged in:</p><ul><li>Unlawful censorship demands on U.S. online platforms.</li><li>Suppressing dissent and targeting political critics.</li><li>Imposing fines on companies refusing to comply and overseeing criminal prosecutions for protected speech.</li></ul></li><li><p><strong>Economic Coercion</strong>: Such actions threaten U.S. companies by:</p><ul><li>Pressuring them to change content policies.</li><li>Exposing them to fines or exclusion from the Brazilian market.</li></ul></li><li><p><strong>Political Persecution</strong>: The prosecution of Jair Bolsonaro:</p><ul><li>Undermines Brazil&#39;s political stability and institutions.</li><li>Threatens free and fair elections in Brazil.</li></ul></li><li><p><strong>National Emergency Declaration</strong>: The order declares a national emergency due to threats stemming largely from Brazil, leading to:</p><ul><li>Imposition of an additional 40% duty on certain Brazilian imports into the U.S.</li></ul></li><li><p><strong>Duty Implementation</strong>:</p><ul><li>Applies to goods entered into the U.S. after a set date, with exceptions for specific products.</li><li>U.S. Customs and Border Protection will administer these duties.</li></ul></li><li><p><strong>Modification Authority</strong>: The President reserves the right to modify duties if Brazil retaliates or takes action to align with U.S. policies.</p></li><li><p><strong>Monitoring and Recommendations</strong>:</p><ul><li>The Secretary of State will monitor the situation and consult with various officials for potential additional actions.</li></ul></li><li><p><strong>Delegation</strong>: The Secretary of State is authorized to implement the order with consultation from relevant agencies.</p></li><li><p><strong>Reporting</strong>: Regular reports will be submitted to Congress regarding the national emergency and actions taken.</p></li><li><p><strong>Severability</strong>: If any part of the order is deemed invalid, the remainder remains effective.</p></li><li><p><strong>General Provisions</strong>: Clarifies that the order does not impair existing legal authorities and does not create enforceable rights against the U.S.</p></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/07/addressing-threats-to-the-us/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/07/addressing-threats-to-the-us/</a></p>',3))]))}});export{u as __pageData,c as default};
